import{_ as t,o as p,c as l,ag as e}from"./chunks/framework.CukOUUOK.js";const g=JSON.parse('{"title":"《标签的背叛》00｜社会、国家与社会主义——一个以\\"社会\\"为名的思想，为什么会产生自己的国家悖论","description":"有些词，最初是用来描述现实的。后来，它们开始规定什么才算现实。再后来，它们甚至可以替现实本身提供合法性。这就是政治标签最危险的地方。“社会主义”。“资本主义”。“民主”。“人民”。“自由”。“共和”。这些词原本都指向某种…","frontmatter":{"title":"《标签的背叛》00｜社会、国家与社会主义——一个以\\"社会\\"为名的思想，为什么会产生自己的国家悖论","categories":"政治思想史","tags":["意识形态","政治思想史","制度","权力"],"description":"有些词，最初是用来描述现实的。后来，它们开始规定什么才算现实。再后来，它们甚至可以替现实本身提供合法性。这就是政治标签最危险的地方。“社会主义”。“资本主义”。“民主”。“人民”。“自由”。“共和”。这些词原本都指向某种…","date":"2026-09-19T12:00:00.000Z","series":"标签的背叛","seriesOrder":0},"headers":[],"relativePath":"posts/2026-09-19-betrayal-of-labels-00.md","filePath":"posts/2026-09-19-betrayal-of-labels-00.md","lastUpdated":1789992750000}'),r={name:"posts/2026-09-19-betrayal-of-labels-00.md"};function a(s,o,n,i,u,c){return p(),l("div",null,[...o[0]||(o[0]=[e('<h1 id="《标签的背叛》00-社会、国家与社会主义——一个以-社会-为名的思想-为什么会产生自己的国家悖论" tabindex="-1">《标签的背叛》00｜社会、国家与社会主义——一个以&quot;社会&quot;为名的思想，为什么会产生自己的国家悖论 <a class="header-anchor" href="#《标签的背叛》00-社会、国家与社会主义——一个以-社会-为名的思想-为什么会产生自己的国家悖论" aria-label="Permalink to &quot;《标签的背叛》00｜社会、国家与社会主义——一个以&quot;社会&quot;为名的思想，为什么会产生自己的国家悖论&quot;">​</a></h1><p>有些词，最初是用来描述现实的。后来，它们开始规定什么才算现实。再后来，它们甚至可以替现实本身提供合法性。这就是政治标签最危险的地方。“社会主义”。“资本主义”。“民主”。“人民”。“自由”。“共和”。这些词原本都指向某种具体的制度关系、政治原则和社会目标。</p><p>可是当一个词被写进国名、写进宪法、写进党章，成为一个政权证明自己“是谁”的依据之后，它就发生了变化。</p><p>它不再只是描述。它开始承担合法性的功能。于是，一个非常重要的问题出现了：</p><blockquote><p><strong>一个制度应该由它叫什么来判断，还是应该由它实际上如何运行来判断？</strong></p></blockquote><p>这就是《标签的背叛》要追问的问题。所谓“背叛”，并不首先意味着某个人背叛了某种主义。更深的意思是：</p><blockquote><p><strong>一个词原本承诺了一种社会关系，后来却可能被一个现实制度拿来证明自己已经实现了这种社会关系。</strong></p></blockquote><p>标签从描述变成证明。从承诺变成凭证。从目的变成合法性来源。于是最需要被追问的，反而被藏到了标签背后：</p><p><strong>这个制度究竟允许谁说“不”？</strong></p><p>因为一个制度真正的内容，从来不完全写在它的名字里。它写在权力关系里。写在谁拥有资源里。写在谁能够组织起来里。写在谁能够拒绝谁里。更重要的是：</p><blockquote><p><strong>当一个强者拒绝改变时，谁有能力迫使他改变？</strong></p></blockquote><p>这就是本系列真正的判据。</p><h3 id="一、社会主义最初面对的-是一个-社会问题" tabindex="-1">一、社会主义最初面对的，是一个“社会问题” <a class="header-anchor" href="#一、社会主义最初面对的-是一个-社会问题" aria-label="Permalink to &quot;一、社会主义最初面对的，是一个“社会问题”&quot;">​</a></h3><p>社会主义产生于19世纪。这是工业革命和资本主义迅速发展的时代。工厂制度出现以后，生产方式发生了根本变化。一个人不再独立完成一件产品。生产越来越依赖复杂的社会协作。</p><p>一件商品背后可能有矿工、钢铁工人、工程师、机械师、运输工人、仓储人员、销售人员共同参与。</p><p>生产越来越社会化。但财富和生产资料的控制，却仍然可以集中于少数私人所有者手中。于是一个巨大的矛盾出现了：</p><blockquote><p><strong>生产是社会性的，占有却可以是私人性的。</strong></p></blockquote><p>这就是早期社会主义者面对的根本问题。所以社会主义一开始并不是：</p><blockquote><p>“让政府管理一切。”</p></blockquote><p>它首先是在问：</p><blockquote><p><strong>一个社会共同创造的财富，为什么不能由这个社会共同决定如何使用？</strong></p></blockquote><p>这也是为什么社会主义这个词中的“社会”，首先不是“国家”的意思。它指的是：共同生活的人们——他们共同劳动、共同生产、共同承担风险、共同创造财富。于是，社会主义最初的基本问题是：</p><blockquote><p><strong>社会能不能把自己创造出来的东西重新掌握在自己手里？</strong></p></blockquote><h3 id="二、马克思把这个问题推进到了生产关系" tabindex="-1">二、马克思把这个问题推进到了生产关系 <a class="header-anchor" href="#二、马克思把这个问题推进到了生产关系" aria-label="Permalink to &quot;二、马克思把这个问题推进到了生产关系&quot;">​</a></h3><p>马克思的贡献，不只是说资本家太富、工人太穷。他的关键转变是：把问题从个人道德转换成制度关系。资本主义不是因为资本家特别坏才产生支配关系。即便一个资本家非常仁慈，只要：</p><ul><li>生产资料归资本所有者；</li><li>劳动者没有生产资料；</li><li>劳动者必须出售劳动力；</li><li>企业必须追求资本积累；</li></ul><p>那么支配关系依然存在。因此，真正的问题不是：</p><blockquote><p>“资本家是不是好人？”</p></blockquote><p>而是：</p><blockquote><p><strong>谁决定劳动条件？</strong></p></blockquote><p>谁决定生产什么？谁决定工作多久？谁决定利润如何使用？谁决定企业如何组织？谁决定劳动者什么时候可以拒绝？这些问题指向同一个地方：</p><p><strong>控制权。</strong></p><p>所以社会主义传统真正激进的地方，不是“让穷人得到更多钱”。而是：</p><blockquote><p><strong>让生产者重新获得对生产条件的控制。</strong></p></blockquote><p>这也是为什么社会主义理论中一直有一个非常重要的词：</p><p><strong>社会所有。</strong></p><p>但这里马上会出现一个20世纪最重要的误会。</p><h3 id="三、社会所有-不等于国家所有" tabindex="-1">三、社会所有，不等于国家所有 <a class="header-anchor" href="#三、社会所有-不等于国家所有" aria-label="Permalink to &quot;三、社会所有，不等于国家所有&quot;">​</a></h3><p>假设一家工厂原来属于私人资本家。革命之后，国家把工厂没收。产权登记改变了。现在：</p><blockquote><p>工厂属于全民。</p></blockquote><p>那么问题解决了吗？还没有。必须继续问：</p><ul><li>谁管理？</li><li>谁任命管理者？</li><li>谁监督管理者？</li><li>工人能不能参与决定生产？</li><li>工人能不能撤换管理者？</li><li>工会能不能与管理层真正谈判？</li><li>消费者能不能影响重大决策？</li><li>地方社会能不能参与？</li></ul><p>如果这些问题的答案都是否定的，那么：私人所有消失了。但：</p><p><strong>社会控制未必出现。</strong></p><p>它可能只是变成了国家所有。因此必须把三个概念分开：</p><p>名义产权决定权归属是否等于社会控制私人所有资本家资本家否国家所有全民（国家代持）国家行政机关未必社会所有社会生产者与共同体是三者不能简单画等号。社会主义所面对的问题，不只是“谁名义上拥有产权”，而是：</p><blockquote><p><strong>谁拥有最终决定权？</strong></p></blockquote><p>现代社会主义理论也因此特别区分“社会权力”和“国家权力”：社会主义所说的社会控制，并不自动意味着国家行政机关替社会作决定。</p><h3 id="四、马克思真正想解决的-恰恰还有国家问题" tabindex="-1">四、马克思真正想解决的，恰恰还有国家问题 <a class="header-anchor" href="#四、马克思真正想解决的-恰恰还有国家问题" aria-label="Permalink to &quot;四、马克思真正想解决的，恰恰还有国家问题&quot;">​</a></h3><p>如果只读后来的制度史，很容易产生一种误解：社会主义就是国家接管生产资料。但马克思主义经典理论其实有另一条非常重要的线索。</p><p>马克思在《哥达纲领批判》中明确批评“自由国家”的观念，认为真正的自由不是让国家成为一个凌驾于社会之上的独立力量，而是使国家这个机关越来越服从于社会。</p><p>这句话的重要性在于：</p><blockquote><p><strong>马克思主义并没有把国家无限膨胀作为社会主义的终点。</strong></p></blockquote><p>相反，它最终指向的是：社会重新掌握公共事务。</p><p>恩格斯后来所说的“国家消亡”，也不是社会消失，而是国家作为一个凌驾于社会之上的特殊强制机器逐渐失去必要。</p><p>列宁在《国家与革命》中进一步把这一逻辑展开。所以，如果把这一脉思想压缩成一句话：</p><blockquote><p><strong>社会主义最终要解决的，不只是资本支配社会，还包括国家作为特殊力量凌驾于社会。</strong></p></blockquote><p>问题也正是在这里开始变得真正困难。</p><h3 id="五、革命为什么如此容易走向国家化" tabindex="-1">五、革命为什么如此容易走向国家化 <a class="header-anchor" href="#五、革命为什么如此容易走向国家化" aria-label="Permalink to &quot;五、革命为什么如此容易走向国家化&quot;">​</a></h3><p>一个社会如果要彻底改变既有制度，需要组织。而现代国家恰恰是人类历史上最强大的组织形式之一。它拥有：军队、警察、行政、财政、司法、教育、交通、工业体系、统计系统与通讯系统。革命者面对旧秩序时，不可能假装国家机器不存在。战争需要集中。资源需要调度。生产需要恢复。敌人需要应对。旧制度需要被推翻。于是革命组织必须迅速获得强大的组织能力。这产生第一个悖论：</p><blockquote><p><strong>为了消灭旧的支配结构，革命必须首先形成一种足以击败旧支配结构的组织。</strong></p></blockquote><p>问题来了。这个组织一旦拥有巨大权力：</p><p><strong>谁保证它会把权力重新交还给社会？</strong></p><p>这才是真正的难题。</p><h3 id="六、最危险的词不是-国家-而是-代表" tabindex="-1">六、最危险的词不是“国家”，而是“代表” <a class="header-anchor" href="#六、最危险的词不是-国家-而是-代表" aria-label="Permalink to &quot;六、最危险的词不是“国家”，而是“代表”&quot;">​</a></h3><p>一个国家可以说：</p><blockquote><p>“我管理社会。”</p></blockquote><p>这句话很容易被理解为统治。但如果它改成：</p><blockquote><p>“我代表社会。”</p></blockquote><p>事情就完全不同了。党代表工人。党代表人民。国家代表人民。国家拥有全民财产。国家制定全民计划。国家决定全民利益。于是一个非常微妙的转换开始发生：</p><blockquote><p><strong>社会主体 → 社会代表 → 代表社会的组织 → 国家机器。</strong></p></blockquote><p>最后：</p><blockquote><p><strong>国家不再只是管理社会，而开始定义什么是社会。</strong></p></blockquote><p>这是“代表”逻辑最危险的地方。如果国家已经代表了整个人民，那么任何提出不同利益的人都会遇到一个问题：</p><p><strong>你代表的是谁？</strong></p><p>如果你代表人民之外的东西，那么你就可能被定义为反人民。如果你声称自己也代表人民，那么就会进入：</p><blockquote><p>“谁才是真正的人民代表？”</p></blockquote><p>的竞争。于是“人民”这个具体的社会主体，就可能逐渐变成一个抽象的政治名词。而一个抽象的“人民”，最容易被一个具体的组织代替。</p><p><strong>这就是全系列将要反复遇到的结构。</strong> 它有一个专门的名字——“谁来守卫守卫者”（<em>Quis custodiet ipsos custodes?</em>），一个自罗马时代起就没有完美答案的问题。</p><h3 id="七、这就是社会主义最大的结构性风险" tabindex="-1">七、这就是社会主义最大的结构性风险 <a class="header-anchor" href="#七、这就是社会主义最大的结构性风险" aria-label="Permalink to &quot;七、这就是社会主义最大的结构性风险&quot;">​</a></h3><p>所以真正危险的不是：国家太强。而是：</p><blockquote><p><strong>国家的组织能力远远超过社会的组织能力。</strong></p></blockquote><p>社会强，不是因为人口多。而是因为人们能够自主组织。</p><ul><li>能够形成工会。</li><li>能够成立行业协会。</li><li>能够建立社区组织。</li><li>能够组成合作社。</li><li>能够办媒体。</li><li>能够进行集体谈判。</li><li>能够监督管理者。</li><li>能够撤换管理者。</li><li>能够对国家说“不”。</li></ul><p>如果一个社会失去了这些能力，那么即使宪法上写着：</p><blockquote><p>“一切权力属于人民。”</p></blockquote><p>人民也可能只剩下一个抽象身份。因为真正的问题是：</p><blockquote><p><strong>人民以什么组织形式拥有国家？</strong></p></blockquote><h3 id="八、于是-反制能力-比-约束-更重要" tabindex="-1">八、于是，“反制能力”比“约束”更重要 <a class="header-anchor" href="#八、于是-反制能力-比-约束-更重要" aria-label="Permalink to &quot;八、于是，“反制能力”比“约束”更重要&quot;">​</a></h3><p>这也是本系列为什么最终不使用“谁能说不”作为总标题的原因。“谁能说不”是一个结果。真正值得研究的是：</p><p><strong>这种“不”为什么能够或者不能够产生效果？</strong></p><p>所以我们需要一个更精确的概念：</p><blockquote><p><strong>反制能力</strong>（countervailing power）：一个受损者能否把“不接受”转化为对强者真正有成本的、持续的、组织化的行动。</p></blockquote><p>它不是私人报复。不是一次愤怒。不是偶发冲突。而必须同时满足：</p><ul><li>能够组织；</li><li>能够持续；</li><li>能够重复启动；</li><li>能够受到规则约束。</li></ul><p>这就引出了五个可检验的问题：</p><p>问题要查什么谁组织？分散的个体没有反制能力；组织起来的才有谁承担组织成本？第一批人可能被开除，第一个领袖可能上绞架谁保证它持续？建立需要百年，衰退只需一代人它怎么避免被收编？掌权者最擅长的不是取消机构，而是让它继续开会却不再能说“不”谁来约束反制者自己？工会也会官僚化，社会组织也会保护既得利益最后这个问题非常重要。因为工会也可能变成官僚机构。社会组织也可能保护既得利益。资本也需要约束。政府也需要约束。劳动者的集体行动同样需要规则。所以：</p><blockquote><p><strong>反制能力不是越多越好，而是必须嵌入一个能够彼此反制的制度结构。</strong></p></blockquote><h3 id="九、标签为什么能挂住-波普尔的警告" tabindex="-1">九、标签为什么能挂住：波普尔的警告 <a class="header-anchor" href="#九、标签为什么能挂住-波普尔的警告" aria-label="Permalink to &quot;九、标签为什么能挂住：波普尔的警告&quot;">​</a></h3><p>到这里必须补上一个机制，否则前三节只是断言：为什么一个已经与内容脱节的标签，还能挂几十年？</p><p>波普尔（Karl Popper）批判<strong>方法论本质主义</strong>（methodological essentialism）：追问事物“真正的本质”是什么，是柏拉图式的遗习；在社会科学中，这种追问会导致<strong>定义即独断</strong>——一旦你宣称掌握了某物的“本质”，你就获得了拒绝一切反例的特权。</p><p>机制是这样的：反例不会被判为“证伪了我的定义”，而会被判为“不符合本质”。于是每一次剥离，都可以被表述为：</p><blockquote><p>“我们更准确地把握了本质。”</p></blockquote><p>而不是：</p><blockquote><p>“我们背离了本质。”</p></blockquote><p><strong>这就是本质话语的免证伪结构。</strong> 它不是在欺骗，它是在用一种<strong>不可被经验反驳的说话方式</strong>说话。</p><p>所以标签能挂住，不是因为内容还在，而是因为<strong>这种说话方式让内容变得不可检验</strong>。</p><p>波普尔主张方法论唯名论：不要问“社会主义的本质是什么”，而要问“我们应当用这个词来要求什么样的可检验状态”。</p><p>这一转换，正是从<strong>定义的政治</strong>走向<strong>检验的政治</strong>。</p><h3 id="十、统一变量-压力传导通道的开放度" tabindex="-1">十、统一变量：压力传导通道的开放度 <a class="header-anchor" href="#十、统一变量-压力传导通道的开放度" aria-label="Permalink to &quot;十、统一变量：压力传导通道的开放度&quot;">​</a></h3><p>本系列三篇案例需要一个统一的测量轴，否则它们只是三个并列的故事。</p><p>它不是“有没有约束”，也不是“制度好不好”，而是一个<strong>连续的、可移动的量</strong>：</p><blockquote><p><strong>一个“不”从受损者那里发出，要经过多少道门，才能变成有效行动；以及——是谁在守这些门。</strong></p></blockquote><p>朝鲜欧洲中国通道状态关闭敞开，正在变窄未闭合自上而下的动作只剩收编回应与收编的混合两者兼有，比例待观察外部标尺已被逐根拔除多元且互相竞争仍在，硬度待检验反制载体从一开始就缺位被组织起来，正在衰退框架完备，启动机制在生长时态已闭合在延续正在进行这个变量的关键优势是：<strong>它是连续的，不是二元的。</strong></p><p>这样，三个案例就不是“坏—好—中间”三档道德排序，而是<strong>同一条轴上的不同位置，而且可以移动</strong>——</p><ul><li>欧洲正在沿着这条轴下滑（法国工会密度已降至约 8%）；</li><li>中国的位置还没定型；</li><li>朝鲜不是“天生如此”，它是从 1948 年那个多派系并存、外部力量在场的格局，<strong>一步步移动</strong>到 2026 年的。</li></ul><p>这一点极其重要，因为它让“没有任何制度一劳永逸”不再是一句附加的免责声明，而是<strong>整个框架的内在结论</strong>。</p><h3 id="十一、这时候-社会主义历史的真正问题才浮现出来" tabindex="-1">十一、这时候，社会主义历史的真正问题才浮现出来 <a class="header-anchor" href="#十一、这时候-社会主义历史的真正问题才浮现出来" aria-label="Permalink to &quot;十一、这时候，社会主义历史的真正问题才浮现出来&quot;">​</a></h3><p>它原本要解决：</p><blockquote><p><strong>资本能不能支配社会？</strong></p></blockquote><p>但在国家化之后，又产生了第二个问题：</p><blockquote><p><strong>国家能不能支配社会？</strong></p></blockquote><p>如果回答只能是：“国家代表人民。”那么问题仍然没有解决。必须继续问：</p><blockquote><p><strong>谁代表国家之外的社会？</strong></p></blockquote><p>如果答案仍然是：“还是这个国家。”那么整个结构就闭合了。社会不再监督国家。社会只能通过国家监督自己。于是出现一个非常讽刺的倒置：</p><blockquote><p><strong>原本是社会控制国家。</strong><br><strong>变成：国家代表社会。</strong><br><strong>再变成：国家定义社会。</strong></p></blockquote><p>这就是社会主义历史最深的悖论之一。</p><h3 id="十二、所以社会主义不是一个终点-而是一组需要不断检验的承诺" tabindex="-1">十二、所以社会主义不是一个终点，而是一组需要不断检验的承诺 <a class="header-anchor" href="#十二、所以社会主义不是一个终点-而是一组需要不断检验的承诺" aria-label="Permalink to &quot;十二、所以社会主义不是一个终点，而是一组需要不断检验的承诺&quot;">​</a></h3><p>真正值得保留下来的社会主义问题，不是：</p><blockquote><p>“社会主义这个标签是不是好听？”</p></blockquote><p>而是：</p><ul><li>生产者有没有控制生产的能力？</li><li>普通人有没有组织起来的能力？</li><li>财富是不是受到社会共同利益的约束？</li><li>国家有没有受到社会控制？</li><li>管理者能不能被监督和撤换？</li><li>任何拥有巨大权力的组织，是否都存在来自社会的反向压力？</li></ul><p>如果这些答案不断是否定的，那么即便一个制度不断强调自己的社会主义性质，也必须重新检查：</p><p><strong>这个标签究竟还在指向什么？</strong></p><h3 id="结语-标签可以继承-内容不能靠继承获得" tabindex="-1">结语：标签可以继承，内容不能靠继承获得 <a class="header-anchor" href="#结语-标签可以继承-内容不能靠继承获得" aria-label="Permalink to &quot;结语：标签可以继承，内容不能靠继承获得&quot;">​</a></h3><p>社会主义历史真正留下的问题，不是：</p><blockquote><p>“社会主义到底好不好？”</p></blockquote><p>这个问题太粗。真正的问题是：</p><blockquote><p><strong>谁拥有决定共同生活的权力？</strong></p></blockquote><p>如果答案是少数资本所有者，那么社会主义的批判出现了。如果资本所有权被消灭，而国家成为唯一的决定者，那么新的问题出现了。如果国家宣称代表人民，那么还必须回答：</p><blockquote><p><strong>人民如何控制这个代表人民的组织？</strong></p></blockquote><p>而如果人民没有独立的组织能力，那么“人民”就可能从主体变成合法性的名词。所以：</p><blockquote><p><strong>社会主义真正危险的不是国家存在，而是社会失去自己的组织能力。</strong></p></blockquote><p>这也是为什么“社会”二字，比“主义”二字更重要。因为社会主义最终真正要回答的，并不是：</p><blockquote><p>国家应该替社会做什么？</p></blockquote><p>而是：</p><blockquote><p><strong>社会能不能自己决定自己的生活？</strong></p></blockquote><p>如果不能，那么标签即使保存得再完整，也可能已经开始背叛它最初承诺的东西。</p><h3 id="附-本系列的四个判据" tabindex="-1">附：本系列的四个判据 <a class="header-anchor" href="#附-本系列的四个判据" aria-label="Permalink to &quot;附：本系列的四个判据&quot;">​</a></h3><p>最后把判据固定下来，后面三篇都用它：</p><ul><li><strong>它承诺了什么？</strong> ——不是看标签，是看它写下的可检验内容。</li><li><strong>这些承诺能不能被检验？</strong> ——是否存在不依赖阐释者本人的标准。</li><li><strong>谁有资格检验？</strong> ——检验者是否需要被检验者授权。</li><li><strong>如果现实不符合承诺，谁能迫使它改变？</strong> ——这是压舱石。</li></ul><p>这四问，比一句“你承不承认它是社会主义”有意义得多。而打破闭环的办法，从来不是换一个更漂亮的标签，而是：</p><blockquote><p><strong>让现实有能力反过来质问标签。</strong></p></blockquote><p>这就是“谁能说不”真正应该处在的位置。它不是这个系列的名字。</p><p><strong>它是这个系列的刀。</strong></p><blockquote><p><strong>下一篇</strong>：01｜朝鲜：一个标签是怎样失去原来含义的<br> 2026 年 3 月，宪法标题里的“社会主义”三个字被摘掉。但真正值得追问的不是这次摘除，而是——在它被摘掉之前，那个标签还挂着的时候，实质已经走了多远。</p></blockquote><hr><blockquote><p>本文同步自知乎，<a href="https://zhuanlan.zhihu.com/p/2084655678568845976" target="_blank" rel="noreferrer">查看原文</a></p></blockquote>',158)])])}const q=t(r,[["render",a]]);export{g as __pageData,q as default};
